create schema if not exists app_private;
revoke all on schema app_private from public, anon;
grant usage on schema app_private to authenticated;
alter table public.lesson_notes add column if not exists published boolean not null default false;
alter table public.exams add column if not exists starts_at timestamptz;
alter table public.exams add column if not exists ends_at timestamptz;
alter table public.exams add column if not exists instructions text;
alter table public.profiles add column if not exists admission_number text;
alter table public.profiles add column if not exists phone text;
create table if not exists public.question_keys(question_id uuid primary key references public.questions(id) on delete cascade,correct_answer jsonb not null);
insert into public.question_keys(question_id,correct_answer) select id,answer_key from public.questions where answer_key is not null on conflict(question_id) do nothing;
alter table public.questions drop column if exists answer_key;
alter table public.question_keys enable row level security;
create unique index if not exists attempt_unique on public.exam_attempts(exam_id,student_id);
create or replace function app_private.my_role() returns text language sql stable security definer set search_path='' as $$ select role from public.profiles where id=(select auth.uid()) limit 1 $$;
create or replace function app_private.my_school() returns uuid language sql stable security definer set search_path='' as $$ select school_id from public.profiles where id=(select auth.uid()) limit 1 $$;
create or replace function app_private.is_admin(s uuid) returns boolean language sql stable security definer set search_path='' as $$ select coalesce((select role='admin' and school_id=s from public.profiles where id=(select auth.uid())),false) $$;
create or replace function app_private.is_parent(st uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.parent_students where parent_id=(select auth.uid()) and student_id=st) $$;
create or replace function app_private.student_class(cl uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.enrollments where class_id=cl and student_id=(select auth.uid())) $$;
create or replace function app_private.parent_class(cl uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.enrollments e join public.parent_students ps on ps.student_id=e.student_id where e.class_id=cl and ps.parent_id=(select auth.uid())) $$;
create or replace function app_private.staff_class(cl uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.classes c where c.id=cl and (app_private.is_admin(c.school_id) or (app_private.my_role()='teacher' and exists(select 1 from public.teacher_assignments a where a.class_id=cl and a.teacher_id=(select auth.uid()))))) $$;
create or replace function app_private.manage_exam(ex uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.exams x join public.classes c on c.id=x.class_id where x.id=ex and ((x.teacher_id=(select auth.uid()) and app_private.my_role()='teacher') or app_private.is_admin(c.school_id))) $$;
create or replace function app_private.exam_visible(ex uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.exams x where x.id=ex and x.published and (x.starts_at is null or now()>=x.starts_at) and (x.ends_at is null or now()<=x.ends_at) and app_private.student_class(x.class_id)) $$;
create or replace function app_private.can_mark(st uuid,sub uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=st and app_private.is_admin(p.school_id)) or (app_private.my_role()='teacher' and exists(select 1 from public.enrollments e join public.teacher_assignments t on t.class_id=e.class_id and t.subject_id=sub where e.student_id=st and t.teacher_id=(select auth.uid()))) $$;
revoke all on all functions in schema app_private from public,anon;
grant execute on all functions in schema app_private to authenticated;
drop policy if exists profile_self_read on public.profiles;
drop policy if exists profile_self_update on public.profiles;
drop policy if exists own_notes on public.lesson_notes;
drop policy if exists own_exams on public.exams;
drop policy if exists own_attempts_read on public.exam_attempts;
drop policy if exists own_attempts_insert on public.exam_attempts;
create policy school_read on public.schools for select to authenticated using(id=app_private.my_school());
create policy profile_read on public.profiles for select to authenticated using(id=(select auth.uid()) or (school_id=app_private.my_school() and app_private.my_role() in ('admin','teacher')) or app_private.is_parent(id));
create policy profile_update on public.profiles for update to authenticated using(id=(select auth.uid()) or app_private.is_admin(school_id)) with check(app_private.is_admin(school_id) or (id=(select auth.uid()) and role=app_private.my_role() and school_id=app_private.my_school()));
create policy session_read on public.academic_sessions for select to authenticated using(school_id=app_private.my_school());
create policy session_write on public.academic_sessions for all to authenticated using(app_private.is_admin(school_id)) with check(app_private.is_admin(school_id));
create policy class_read on public.classes for select to authenticated using(school_id=app_private.my_school());
create policy class_write on public.classes for all to authenticated using(app_private.is_admin(school_id)) with check(app_private.is_admin(school_id));
create policy subject_read on public.subjects for select to authenticated using(school_id=app_private.my_school());
create policy subject_write on public.subjects for all to authenticated using(app_private.is_admin(school_id)) with check(app_private.is_admin(school_id));
create policy enrollment_read on public.enrollments for select to authenticated using(student_id=(select auth.uid()) or app_private.is_parent(student_id) or app_private.staff_class(class_id));
create policy enrollment_write on public.enrollments for all to authenticated using(exists(select 1 from public.classes c where c.id=class_id and app_private.is_admin(c.school_id))) with check(exists(select 1 from public.classes c join public.profiles p on p.id=student_id and p.role='student' and p.school_id=c.school_id where c.id=class_id and app_private.is_admin(c.school_id)));
create policy assignment_read on public.teacher_assignments for select to authenticated using(teacher_id=(select auth.uid()) or exists(select 1 from public.classes c where c.id=class_id and app_private.is_admin(c.school_id)));
create policy assignment_write on public.teacher_assignments for all to authenticated using(exists(select 1 from public.classes c where c.id=class_id and app_private.is_admin(c.school_id))) with check(exists(select 1 from public.classes c join public.profiles p on p.id=teacher_id and p.role='teacher' and p.school_id=c.school_id join public.subjects s on s.id=subject_id and s.school_id=c.school_id where c.id=class_id and app_private.is_admin(c.school_id)));
create policy parentlink_read on public.parent_students for select to authenticated using(parent_id=(select auth.uid()) or app_private.is_admin(app_private.my_school()));
create policy parentlink_write on public.parent_students for all to authenticated using(app_private.is_admin(app_private.my_school())) with check(app_private.is_admin(app_private.my_school()) and exists(select 1 from public.profiles p join public.profiles s on s.id=student_id where p.id=parent_id and p.role='parent' and s.role='student' and p.school_id=s.school_id and s.school_id=app_private.my_school()));
create policy lesson_read on public.lesson_notes for select to authenticated using(teacher_id=(select auth.uid()) or (class_id is not null and app_private.staff_class(class_id)) or (published and class_id is not null and (app_private.student_class(class_id) or app_private.parent_class(class_id))));
create policy lesson_insert on public.lesson_notes for insert to authenticated with check(teacher_id=(select auth.uid()) and app_private.my_role() in ('admin','teacher') and (class_id is null or app_private.staff_class(class_id)));
create policy lesson_update on public.lesson_notes for update to authenticated using(teacher_id=(select auth.uid()) and app_private.my_role() in ('admin','teacher')) with check(teacher_id=(select auth.uid()) and (class_id is null or app_private.staff_class(class_id)));
create policy lesson_delete on public.lesson_notes for delete to authenticated using(teacher_id=(select auth.uid()) and app_private.my_role() in ('admin','teacher'));
create policy exam_read on public.exams for select to authenticated using(app_private.manage_exam(id) or app_private.exam_visible(id));
create policy exam_insert on public.exams for insert to authenticated with check(teacher_id=(select auth.uid()) and exists(select 1 from public.classes c where c.id=class_id and (app_private.is_admin(c.school_id) or exists(select 1 from public.teacher_assignments t where t.teacher_id=(select auth.uid()) and t.class_id=c.id and t.subject_id=subject_id))));
create policy exam_update on public.exams for update to authenticated using(app_private.manage_exam(id)) with check(teacher_id=(select auth.uid()) or app_private.is_admin(app_private.my_school()));
create policy exam_delete on public.exams for delete to authenticated using(app_private.manage_exam(id));
create policy question_read on public.questions for select to authenticated using(app_private.manage_exam(exam_id) or app_private.exam_visible(exam_id));
create policy question_write on public.questions for all to authenticated using(app_private.manage_exam(exam_id)) with check(app_private.manage_exam(exam_id));
create policy key_read on public.question_keys for select to authenticated using(exists(select 1 from public.questions q where q.id=question_id and app_private.manage_exam(q.exam_id)));
create policy key_write on public.question_keys for all to authenticated using(exists(select 1 from public.questions q where q.id=question_id and app_private.manage_exam(q.exam_id))) with check(exists(select 1 from public.questions q where q.id=question_id and app_private.manage_exam(q.exam_id)));
create policy attempt_read on public.exam_attempts for select to authenticated using(student_id=(select auth.uid()) or app_private.manage_exam(exam_id));
create policy answer_read on public.student_answers for select to authenticated using(exists(select 1 from public.exam_attempts a where a.id=attempt_id and (a.student_id=(select auth.uid()) or app_private.manage_exam(a.exam_id))));
create policy attendance_read on public.attendance for select to authenticated using(student_id=(select auth.uid()) or app_private.is_parent(student_id) or app_private.staff_class(class_id));
create policy attendance_write on public.attendance for all to authenticated using(app_private.staff_class(class_id)) with check(app_private.staff_class(class_id) and exists(select 1 from public.enrollments e where e.class_id=attendance.class_id and e.student_id=attendance.student_id));
create policy assessment_read on public.assessments for select to authenticated using(student_id=(select auth.uid()) or app_private.is_parent(student_id) or app_private.can_mark(student_id,subject_id));
create policy assessment_write on public.assessments for all to authenticated using(app_private.can_mark(student_id,subject_id)) with check(app_private.can_mark(student_id,subject_id));
create policy report_read on public.report_cards for select to authenticated using(app_private.is_admin(app_private.my_school()) or (approved_at is not null and (student_id=(select auth.uid()) or app_private.is_parent(student_id))) or exists(select 1 from public.enrollments e where e.student_id=report_cards.student_id and app_private.staff_class(e.class_id)));
create policy report_write on public.report_cards for all to authenticated using(app_private.is_admin(app_private.my_school())) with check(app_private.is_admin(app_private.my_school()));
create policy announcement_read on public.announcements for select to authenticated using(school_id=app_private.my_school());
create policy announcement_insert on public.announcements for insert to authenticated with check(author_id=(select auth.uid()) and school_id=app_private.my_school() and app_private.my_role() in ('teacher','admin'));
create policy announcement_update on public.announcements for update to authenticated using(author_id=(select auth.uid()) or app_private.is_admin(school_id)) with check(school_id=app_private.my_school());
create policy announcement_delete on public.announcements for delete to authenticated using(author_id=(select auth.uid()) or app_private.is_admin(school_id));
insert into public.schools(name) select 'Torch Bearers Academy' where not exists(select 1 from public.schools where name='Torch Bearers Academy');